	Item1                       *int32
	Item2                       *int32
	Item3                       *int32
	Item4                       *int32
	Item5                       *int32
	Item6                       *int32
	Summoner1ID                 *int32
	Summoner2ID                 *int32
	GameEndedInEarlySurrender   *bool
	GameEndedInSurrender        *bool
	Style0                      *int32
	Style1                      *int32
	Perk0                       *int32
	Perk1                       *int32
	Perk2                       *int32
	Perk3                       *int32
	Perk4                       *int32
	Perk5                       *int32
